mapper.select:
SELECT 
FROM campus_clue
WHERE deleted = 0

    AND COALESCE(publish_time, discover_time, create_time) >= #{startTime}


    AND COALESCE(publish_time, discover_time, create_time) <= #{endTime}


    AND (

        clue_title LIKE CONCAT('%', #{keyword}, '%')
        OR clue_content LIKE CONCAT('%', #{keyword}, '%')
        OR keywords LIKE CONCAT('%', #{keyword}, '%')

    )

ORDER BY COALESCE(publish_time, discover_time, create_time) DESC, id DESC
LIMIT #{limit}

